import pathlib,json,hashlib,subprocess,html
P=pathlib.Path(__file__).resolve().parent;R=pathlib.Path.cwd(); C=P.parent/'candidate-prepare-correction'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,x):(P/n).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf8')
frozen_drift=[k for k,v in read(P.parent/'candidate-prepare-review/source-hashes.json').items() if sha(R/k)!=v];assert frozen_drift==['docs/board.json']
src=read(C/'source-current.json');drift=[k for k,v in src['current_hashes'].items() if sha(R/k)!=v];assert not drift
head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();assert head==src['HEAD']
review={'status':'PASS_DOCUMENT_LEXICAL_CORRECTION_SCOPE_ONLY_PENDING_OWNER','author':'/root/m03_prepare_lexical_correction','reviewer':'/root/m03_prepare_correction_review','scope':'design_candidate_prepare lexical document correction only','closures':{'CP-R1':'CLOSED: complete request binding_ref LF rejected','CP-R2':'CLOSED: complete request request_id LF rejected'},'findings':[],'patterns':'8 physical; 4 U64 unchanged; 2 UUID and 2 unreachable Digest strict end only','routes':9,'preservation':'Non-pattern schema canonical equality; 9 semantic/policy files byte preserved; original frozen candidate hashes verified; prior board snapshot drift only (parent update)','open_owner':read(P.parent/'candidate-prepare-review/review.json')['open_owner'],'limits':['Guard/trust predicates remain prior limited evidence, not new defects.','Digest definitions unreachable from complete roots; no invented digest field.','Subset validator only; full Draft2020-12 NOT RUN.','No Owner approval, architecture acceptance, Skeleton or valid native RED.','No other command, old save path, full PREP card or product acceptance.'],'not_run':['fullDraft','Owner adoption','product','native','RED','GREEN','build','package','install'],'source':{'HEAD':head,'branch':src['branch'],'authority_path':src['authority_path'],'authority_count':src['authority_count'],'current_product_hashes_verified':len(src['current_hashes']),'drift':drift,'M01':'S2 green authority preserved'},'board':'PD-P1-M03-PREP-01 remains yellow; current-state unchanged'}
write('review.json',review)
write('verification.json',{'status':'PASS','command':'python -B probes.py; python -B check_review.py','probe_results':read(P/'probe-results.json'),'boundary':'Document-only independent verification; all product stages NOT RUN'})
files=[x for x in C.iterdir() if x.is_file()]+[P.parent/'current-state.json',R/'docs/board.json',R/'docs/requirements-confirmation/phase1-spec/tasks/PD-P1-M03-PREP-01.json']
write('source-hashes.json',{str(x.relative_to(R)).replace('\\','/'):sha(x) for x in files})
(P/'index.html').write_text('<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>M03 lexical correction independent review</title><style>body{font:16px system-ui;max-width:1000px;margin:40px auto;line-height:1.7}pre{white-space:pre-wrap;background:#eee;padding:20px}</style><h1>M03 獨立文件補正審查</h1><p>PASS_DOCUMENT_LEXICAL_CORRECTION_SCOPE_ONLY_PENDING_OWNER</p><p>CP-R1、CP-R2 已閉合。8 個實體 pattern、9 條根路徑；Python / Node 各 202 個字串案例，16 組完整根物件邊界 probes。4 個 U64 原已嚴格結尾且不變。兩個 UUID 與兩個未使用 Digest 僅修正結尾。</p><p>Owner slot replacement/replay 決策維持 OPEN_OWNER；fullDraft、產品/native/RED/build 仍 NOT RUN。原 guard/trust 限制不重列為新 finding。未改產品、原文件、board 或 current-state。</p><pre>'+html.escape(json.dumps(review,ensure_ascii=False,indent=2))+'</pre><a href="probe-results.json">Independent probe evidence</a></html>',encoding='utf8')
write('artifact-hashes.json',{x.name:sha(x) for x in P.iterdir() if x.is_file() and x.name!='artifact-hashes.json'})
print('PASS review artifact created')

